-- 0186_distribution_finalise_gate.sql - SC-5.D.02
--
-- Approve-to-finalise gate for trust distribution minutes.
--
-- The distribution engine writes draft trust_distributions rows (0158). The
-- minute PDF is generated by the trust-minute edge function (SC-5.D.01). This
-- RPC is the state transition: draft/approved -> finalised, but only when a
-- live Tier-2 approval is bound to the exact rows being finalised AND the
-- minute PDF hash presented to the approver.
--
-- MIGRATION NUMBER: ledger planned 0150, but 0150 is already used by the Phase
-- 4 CGT/book-to-tax chain. Current repo head is 0185_accountant_orchestrator_
-- cron.sql, so this slice is reassigned to 0186 per the drift rule.

create or replace function public.distribution_finalise_payload(
  p_org uuid,
  p_trust uuid,
  p_fy_start_year integer,
  p_minute_pdf_hash text
)
returns jsonb
language sql
stable
security invoker
set search_path = public
as $$
  with candidate_rows as (
    select
      td.id,
      td.beneficiary_id,
      td.financial_year,
      td.amount_cents,
      td.capital_gain_cents,
      td.franked_dividend_cents,
      td.other_cents,
      td.franking_credits_cents,
      td.status
    from public.trust_distributions td
    where td.organization_id = p_org
      and td.trust_id = p_trust
      and td.financial_year = p_fy_start_year
      and td.status in ('draft', 'approved')
      and td.deleted_at is null
  )
  select jsonb_build_object(
    'resource_type', 'trust_distribution_finalise',
    'organization_id', p_org,
    'trust_id', p_trust,
    'fy_start_year', p_fy_start_year,
    'minute_pdf_hash', lower(trim(coalesce(p_minute_pdf_hash, ''))),
    'distributions', coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', cr.id,
          'beneficiary_id', cr.beneficiary_id,
          'financial_year', cr.financial_year,
          'amount_cents', cr.amount_cents,
          'capital_gain_cents', cr.capital_gain_cents,
          'franked_dividend_cents', cr.franked_dividend_cents,
          'other_cents', cr.other_cents,
          'franking_credits_cents', cr.franking_credits_cents,
          'status', cr.status
        )
        order by cr.beneficiary_id, cr.id
      ) filter (where cr.id is not null),
      '[]'::jsonb
    )
  )
  from candidate_rows cr;
$$;

comment on function public.distribution_finalise_payload(uuid, uuid, integer, text) is
  'SC-5.D.02 canonical approval payload for finalising trust distributions. '
  'Binds the exact draft/approved distribution rows and the minute PDF sha256 '
  'hash, so approval is invalidated if rows or the signed minute content change.';

create or replace function public.distribution_finalise(
  p_org uuid,
  p_trust uuid,
  p_fy_start_year integer,
  p_minute_pdf_hash text
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = public
as $$
declare
  v_hash text := lower(trim(coalesce(p_minute_pdf_hash, '')));
  v_payload jsonb;
  v_candidate_count integer := 0;
  v_duplicate_beneficiary uuid;
  v_superseded_count integer := 0;
  v_finalised_count integer := 0;
  v_finalised_rows jsonb := '[]'::jsonb;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if p_org not in (select public.get_accessible_org_ids()) then
    raise exception 'organization not accessible';
  end if;

  if v_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'minute_pdf_hash must be a 64-character sha256 hex digest'
      using errcode = 'invalid_parameter_value';
  end if;

  select td.beneficiary_id
    into v_duplicate_beneficiary
    from public.trust_distributions td
   where td.organization_id = p_org
     and td.trust_id = p_trust
     and td.financial_year = p_fy_start_year
     and td.status in ('draft', 'approved')
     and td.deleted_at is null
   group by td.beneficiary_id
  having count(*) > 1
   limit 1;

  if v_duplicate_beneficiary is not null then
    raise exception 'multiple live draft/approved distributions for beneficiary %',
      v_duplicate_beneficiary
      using errcode = 'invalid_parameter_value';
  end if;

  v_payload := public.distribution_finalise_payload(
    p_org,
    p_trust,
    p_fy_start_year,
    v_hash
  );
  v_candidate_count := jsonb_array_length(v_payload -> 'distributions');

  if v_candidate_count = 0 then
    raise exception 'no draft or approved distributions to finalise'
      using errcode = 'invalid_parameter_value';
  end if;

  if not public.is_action_approved(
    p_org,
    'trust_distribution_finalise',
    p_trust,
    v_payload
  ) then
    raise exception 'approval required before finalising this trust distribution minute';
  end if;

  with approved_candidates as (
    select
      (row_value ->> 'id')::uuid as id,
      (row_value ->> 'beneficiary_id')::uuid as beneficiary_id
    from jsonb_array_elements(v_payload -> 'distributions') as row_value
  ),
  retired as (
    update public.trust_distributions old
       set deleted_at = now()
     where old.organization_id = p_org
       and old.trust_id = p_trust
       and old.financial_year = p_fy_start_year
       and old.status = 'finalised'
       and old.deleted_at is null
       and old.beneficiary_id in (
         select c.beneficiary_id from approved_candidates c
       )
    returning old.id
  ),
  finalised as (
    update public.trust_distributions td
       set status = 'finalised'
     where td.id in (select c.id from approved_candidates c)
       and td.organization_id = p_org
       and td.trust_id = p_trust
       and td.financial_year = p_fy_start_year
       and td.status in ('draft', 'approved')
       and td.deleted_at is null
    returning
      td.id,
      td.beneficiary_id,
      td.amount_cents,
      td.capital_gain_cents,
      td.franked_dividend_cents,
      td.other_cents,
      td.franking_credits_cents,
      td.status
  )
  select
    (select count(*) from retired),
    (select count(*) from finalised),
    coalesce(
      (select jsonb_agg(
        jsonb_build_object(
          'id', id,
          'beneficiary_id', beneficiary_id,
          'amount_cents', amount_cents,
          'capital_gain_cents', capital_gain_cents,
          'franked_dividend_cents', franked_dividend_cents,
          'other_cents', other_cents,
          'franking_credits_cents', franking_credits_cents,
          'status', status
        )
        order by beneficiary_id, id
      ) from finalised),
      '[]'::jsonb
  )
  into v_superseded_count, v_finalised_count, v_finalised_rows;

  if v_finalised_count <> v_candidate_count then
    raise exception 'approved distribution rows changed before finalise'
      using errcode = 'serialization_failure';
  end if;

  return jsonb_build_object(
    'ok', true,
    'organization_id', p_org,
    'trust_id', p_trust,
    'fy_start_year', p_fy_start_year,
    'minute_pdf_hash', v_hash,
    'approval_resource_type', 'trust_distribution_finalise',
    'approval_resource_id', p_trust,
    'approval_payload', v_payload,
    'finalised_count', v_finalised_count,
    'superseded_finalised_count', v_superseded_count,
    'finalised', v_finalised_rows
  );
end;
$$;

comment on function public.distribution_finalise(uuid, uuid, integer, text) is
  'SC-5.D.02: finalises trust_distributions for a trust/FY only after a live '
  'Tier-2 approval is bound to distribution_finalise_payload(...), including '
  'the exact draft/approved rows and the minute PDF sha256 hash. SECURITY '
  'INVOKER; trust_distributions RLS scopes reads/writes to the caller org.';

revoke all on function public.distribution_finalise_payload(uuid, uuid, integer, text) from public, anon;
revoke all on function public.distribution_finalise(uuid, uuid, integer, text) from public, anon;
grant execute on function public.distribution_finalise_payload(uuid, uuid, integer, text) to authenticated, service_role;
grant execute on function public.distribution_finalise(uuid, uuid, integer, text) to authenticated;

notify pgrst, 'reload schema';
